import{_ as t,o,c as a,aF as r}from"./chunks/framework.CNkxH4QO.js";const u=JSON.parse('{"title":"krawler-openaq","description":"A Krawler based job to download data from OpenAQ.","frontmatter":{"title":"krawler-openaq","description":"A Krawler based job to download data from OpenAQ."},"headers":[],"relativePath":"packages/krawler-openaq/index.md","filePath":"packages/krawler-openaq/index.md"}'),d={name:"packages/krawler-openaq/index.md"};function n(i,e,l,c,s,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="krawler-openaq" tabindex="-1">krawler-openaq <a class="header-anchor" href="#krawler-openaq" aria-label="Permalink to &quot;krawler-openaq&quot;">​</a></h1><p><em>A Krawler based job to download data from <a href="https://openaq.org" target="_blank" rel="noreferrer">OpenAQ</a>.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-openaq</strong> job downloads <strong>OpenAQ</strong> data for a given list of countries.</p><p>The available parameters are:</p><ul><li><code>pm25</code>: particulate matter PM255</li><li><code>pm10</code>: Particulate matter PM10</li><li><code>so2</code>: Sulphur dioxide</li><li><code>no2</code>: Nitrogen dioxide</li><li><code>o3</code>: Ozone</li><li><code>co</code>: Carbon monoxide</li></ul><p>The job relies on the <a href="https://docs.openaq.org/api" target="_blank" rel="noreferrer">OpenAQ API v3.0</a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>See the <a href="https://docs.openaq.org/resources/countries" target="_blank" rel="noreferrer">Countries</a> documentation to learn how to obtain the list of countries.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Since the API version 3, it is required to get an <a href="https://docs.openaq.org/using-the-api/quick-start" target="_blank" rel="noreferrer">API Key</a>.</p></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="locations" tabindex="-1">locations <a class="header-anchor" href="#locations" aria-label="Permalink to &quot;locations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>API_KEY</code></td><td>the API Key.</td></tr><tr><td><code>COUNTRIES</code></td><td>a list specifying the countries to be taken into account. By default: <code>22,129</code></td></tr><tr><td><code>LOOKBACK_PERIOD</code></td><td>The period, starting from now, that determines when a location becomes invalid. By default <code>P3M</code>.</td></tr><tr><td><code>DB_URL</code></td><td>the database url. By default: <code>mongodb://localhost:27017/openaq</code></td></tr></tbody></table><h3 id="measurements" tabindex="-1">measurements <a class="header-anchor" href="#measurements" aria-label="Permalink to &quot;measurements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>API_KEY</code></td><td>the API Key.</td></tr><tr><td><code>LOOKBACK_PERIOD</code></td><td>The period, starting from now, that determines when a measurement has to be ignored. By default <code>PT3H</code>.</td></tr><tr><td><code>DELAY</code></td><td>The delay in milliseconds to wait before executing the next request to the API. Default is <code>1200</code>.</td></tr><tr><td><code>TTL</code></td><td>The retention period in seconds of the data. By default: <code>7 * 24 * 60 * 60</code> (7 days)</td></tr><tr><td><code>TIMEOUT</code></td><td>the job timeout in milliseconds. By default: <code>3600000</code> (1 hour)</td></tr><tr><td><code>DB_URL</code></td><td>the database url. By default: <code>mongodb://localhost:27017/openaq</code></td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p>',16)])])}const b=t(d,[["render",n]]);export{u as __pageData,b as default};
